    /**
     * @method
     * @name zebpay#fetchTradingFees
     * @description fetch the trading fees for multiple markets
     * @see [Swap] https://github.com/zebpay/zebpay-api-references/blob/main/futures/api-reference/public-endpoints/exchange.md#get-trade-fees-all-symbols
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {object} a [status structure]{@link https://docs.ccxt.com/?id=exchange-status-structure}
     */
    public CompletableFuture<TradingFees> fetchTradingFees(Map<String, Object> parameters)
    {

        return BaseExchange.supplyAsync(() -> {

            List<Object> typeparamsMarketTypeVariable = (List<Object>) this.handleMarketTypeAndParams("fetchTradingFees", (Map<String, Object>) null, parameters, (Object) null);
            String type = (String) ((List<Object>) typeparamsMarketTypeVariable).get(0);
            Map<String, Object> paramsMarketType = (Map<String, Object>) ((List<Object>) typeparamsMarketTypeVariable).get(1);
            Map<String, Object> response = null;
            if (java.util.Objects.equals(type, "spot"))
            {
                response = (this.publicSpotGetV2ExTradefees(paramsMarketType)).join();
            } else
            {
                response = (this.publicSwapGetV1ExchangeTradefees(paramsMarketType)).join();
            }
            //
            // {
            //     "statusDescription": "OK",
            //     "data": [
            //         {
            //             "symbol": "BTCINR",
            //             "takerFee": "0.01",
            //             "makerFee": "0.05"
            //         }
            //     ],
            //     "statusCode": 200,
            //     "customMessage": ["OK"]
            // }
            //
            List<Object> fees = (List<Object>) this.safeList(response, "data", new ArrayList<Object>(Arrays.asList()));
            Map<String, Object> result = new HashMap<String, Object>() {{}};
            for (var i = 0; i < ((List<?>)fees).size(); i++)
            {
                Map<String, Object> fee = this.parseTradingFee((Map<String, Object>) ((fees == null || i < 0 || i >= fees.size() ? null : fees.get(i))), (Map<String, Object>) null);
                String symbol = (String) ((Map<String, Object>)fee).get("symbol");
                if (!java.util.Objects.equals(symbol, null))
                {
                    result.put((String)symbol, fee);
                }
            }
            return result;
        }).thenApply(TradingFees::new);

    }

